def sudoku(rows: list[str]) -> bool:
    if len(rows) != 9:
        return False
    for row in rows:
        if len(row) != 9:
            return False
        for ch in row:
            if ch != "." and ch not in "123456789":
                return False

    rows_seen = [set() for _ in range(9)]
    cols_seen = [set() for _ in range(9)]
    boxes_seen = [set() for _ in range(9)]
    for r in range(9):
        for c in range(9):
            ch = rows[r][c]
            if ch == ".":
                continue
            box = (r // 3) * 3 + (c // 3)
            if ch in rows_seen[r] or ch in cols_seen[c] or ch in boxes_seen[box]:
                return False
            rows_seen[r].add(ch)
            cols_seen[c].add(ch)
            boxes_seen[box].add(ch)
    return True
